// Generates one indexable page per language from docs/index.html.
//
//   node scripts/build-lang-pages.js          write docs/<lang>/index.html, sitemap, robots, hreflang
//   node scripts/build-lang-pages.js --check  fail if any generated file is out of date (npm test)
//
// Why: docs/index.html carries all 34 languages at once and picks one in the
// browser from navigator.languages. Googlebot sends no language, so it only
// ever indexed the English text — the other 33 translations brought no search
// traffic at all (found 2026-10-18 when Google Ads' keyword planner, pointed at
// the site, returned English keywords only). Each language now gets its own URL
// with only its own text, its own <title>/description/canonical, and hreflang
// links tying all of them together.
//
// docs/index.html stays the ONLY hand-edited source of the landing page (see
// README.md). Everything under docs/<lang>/, docs/sitemap.xml, docs/robots.txt
// and the hreflang block inside docs/index.html is output of this script:
// edit index.html, then run it.
//
// English is the root itself (`/`, also x-default), so there is no docs/en/:
// two English URLs would just be duplicate content.

const fs = require('fs');
const path = require('path');

const SITE = 'https://chronosintelligentalarm.com';
const root = path.join(__dirname, '..');
const docs = path.join(root, 'docs');
const sourcePath = path.join(docs, 'index.html');

// og:locale needs language_TERRITORY; one sensible default per language.
const OG_LOCALE = {
  en: 'en_US', es: 'es_ES', fr: 'fr_FR', de: 'de_DE', pt: 'pt_BR', it: 'it_IT',
  zh: 'zh_CN', ja: 'ja_JP', ko: 'ko_KR', nl: 'nl_NL', id: 'id_ID', el: 'el_GR',
  fil: 'fil_PH', sv: 'sv_SE', da: 'da_DK', nb: 'nb_NO', fi: 'fi_FI', pl: 'pl_PL',
  cs: 'cs_CZ', hu: 'hu_HU', tr: 'tr_TR', ru: 'ru_RU', uk: 'uk_UA', hi: 'hi_IN',
  th: 'th_TH', ar: 'ar_AR', fa: 'fa_IR', ur: 'ur_PK', ca: 'ca_ES', ms: 'ms_MY',
  ro: 'ro_RO', vi: 'vi_VN', he: 'he_IL', bn: 'bn_BD',
};

const HREFLANG_START = '<!-- hreflang:start (generated by scripts/build-lang-pages.js, do not edit) -->';
const HREFLANG_END = '<!-- hreflang:end -->';

const urlFor = (lang) => (lang === 'en' ? `${SITE}/` : `${SITE}/${lang}/`);

function fail(msg) {
  console.error(`build-lang-pages: ${msg}`);
  process.exit(1);
}

function readLanguages(html) {
  const block = html.match(/var CHRONOS_LANGS = \[([\s\S]*?)\];/);
  if (!block) fail('CHRONOS_LANGS not found in docs/index.html');
  const langs = [...block[1].matchAll(/\['([a-z]+)',/g)].map((m) => m[1]);
  const rtl = html.match(/var CHRONOS_RTL = \[([^\]]*)\]/);
  if (!rtl) fail('CHRONOS_RTL not found in docs/index.html');
  return { langs, rtl: [...rtl[1].matchAll(/'([a-z]+)'/g)].map((m) => m[1]) };
}

// Every translated string is a `<span data-key="…" data-l="xx">…</span>` that
// may contain markup of its own (including nested spans, e.g. hero.h1), so the
// closing tag is found by counting depth, not by regex.
const OPEN = /<span data-key="([^"]+)" data-l="([a-z]+)">/g;

function closingEnd(html, from) {
  const tag = /<span\b|<\/span>/g;
  tag.lastIndex = from;
  let depth = 1;
  let m;
  while ((m = tag.exec(html))) {
    depth += m[0] === '</span>' ? -1 : 1;
    if (depth === 0) return m.index + m[0].length;
  }
  fail(`unbalanced <span> after offset ${from}`);
}

function keepOnly(html, lang) {
  let out = '';
  let pos = 0;
  OPEN.lastIndex = 0;
  let m;
  while ((m = OPEN.exec(html))) {
    const end = closingEnd(html, OPEN.lastIndex);
    out += html.slice(pos, m.index);
    if (m[2] === lang) out += html.slice(m.index, end);
    pos = end;
    OPEN.lastIndex = end;
  }
  return out + html.slice(pos);
}

function text(html, key, lang) {
  OPEN.lastIndex = 0;
  let m;
  while ((m = OPEN.exec(html))) {
    if (m[1] === key && m[2] === lang) {
      const inner = html.slice(OPEN.lastIndex, closingEnd(html, OPEN.lastIndex) - '</span>'.length);
      return inner.replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
    }
  }
  fail(`no "${key}" text for "${lang}"`);
}

const attr = (s) => s.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');

function hreflangBlock(langs) {
  const lines = langs.map((l) => `<link rel="alternate" hreflang="${l}" href="${urlFor(l)}">`);
  lines.push(`<link rel="alternate" hreflang="x-default" href="${urlFor('en')}">`);
  return `${HREFLANG_START}\n${lines.join('\n')}\n${HREFLANG_END}`;
}

function withHreflang(html, langs) {
  const block = hreflangBlock(langs);
  const existing = new RegExp(`${escapeRe(HREFLANG_START)}[\\s\\S]*?${escapeRe(HREFLANG_END)}`);
  if (existing.test(html)) return html.replace(existing, block);
  return html.replace(/(<link rel="canonical"[^>]*>)/, `$1\n${block}`);
}

function escapeRe(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

// Replaces exactly one occurrence, so a changed <head> fails loudly instead of
// silently shipping an English title on a Spanish page.
function replaceOnce(html, re, value, what) {
  const hits = html.match(new RegExp(re.source, 'g'));
  if (!hits || hits.length !== 1) fail(`expected exactly one ${what}, found ${hits ? hits.length : 0}`);
  return html.replace(re, value);
}

function langPage(source, lang, rtl) {
  const title = `Chronos — ${text(source, 'hero.eyebrow', lang)}`;
  const description = text(source, 'hero.tagline', lang);
  const url = urlFor(lang);
  let html = keepOnly(source, lang);

  html = replaceOnce(html, /<html lang="en">/,
    `<html lang="${lang}" data-lang="${lang}"${rtl.includes(lang) ? ' dir="rtl"' : ''}>`, '<html lang="en">');
  html = replaceOnce(html, /<title>[^<]*<\/title>/, `<title>${attr(title)}</title>`, '<title>');
  html = replaceOnce(html, /<meta name="description" content="[^"]*">/,
    `<meta name="description" content="${attr(description)}">`, 'meta description');
  html = replaceOnce(html, /<link rel="canonical" href="[^"]*">/, `<link rel="canonical" href="${url}">`, 'canonical');
  html = replaceOnce(html, /<meta property="og:url" content="[^"]*">/, `<meta property="og:url" content="${url}">`, 'og:url');
  html = replaceOnce(html, /<meta property="og:title" content="[^"]*">/, `<meta property="og:title" content="${attr(title)}">`, 'og:title');
  html = replaceOnce(html, /<meta property="og:description" content="[^"]*">/,
    `<meta property="og:description" content="${attr(description)}">`, 'og:description');
  html = replaceOnce(html, /<meta property="og:locale" content="[^"]*">/,
    `<meta property="og:locale" content="${OG_LOCALE[lang]}">`, 'og:locale');
  html = replaceOnce(html, /<meta property="og:locale:alternate" content="[^"]*">\n/, '', 'og:locale:alternate');
  html = replaceOnce(html, /<meta name="twitter:title" content="[^"]*">/, `<meta name="twitter:title" content="${attr(title)}">`, 'twitter:title');
  html = replaceOnce(html, /<meta name="twitter:description" content="[^"]*">/,
    `<meta name="twitter:description" content="${attr(description)}">`, 'twitter:description');

  // The page's language is its URL, not the visitor's browser: the head script
  // reads this before anything paints (see chronosDetectLang).
  html = replaceOnce(html, /  var CHRONOS_LANGS = \[/,
    `  var CHRONOS_PAGE_LANG = '${lang}';\n  var CHRONOS_LANGS = [`, 'CHRONOS_LANGS declaration');

  // One level deeper than the root: relative asset and page links go up one.
  html = html.replace(/(href|src)="(assets\/|contact\/)/g, '$1="../$2');
  return html;
}

function sitemap(langs) {
  const alternates = langs
    .map((l) => `    <xhtml:link rel="alternate" hreflang="${l}" href="${urlFor(l)}"/>`)
    .concat(`    <xhtml:link rel="alternate" hreflang="x-default" href="${urlFor('en')}"/>`)
    .join('\n');
  const urls = langs.map((l) => `  <url>\n    <loc>${urlFor(l)}</loc>\n${alternates}\n  </url>`).join('\n');
  return '<?xml version="1.0" encoding="UTF-8"?>\n'
    + '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">\n'
    + `${urls}\n</urlset>\n`;
}

const robots = `User-agent: *\nAllow: /\n\nSitemap: ${SITE}/sitemap.xml\n`;

function build() {
  const source = fs.readFileSync(sourcePath, 'utf8');
  if (source.includes('\r')) fail('docs/index.html has CRLF line endings; expected LF');
  const { langs, rtl } = readLanguages(source);
  for (const l of langs) if (!OG_LOCALE[l]) fail(`no og:locale for "${l}": add it to OG_LOCALE`);
  if (langs[0] !== 'en') fail('English must be the first language (it is the root page)');

  const files = new Map();
  const rootHtml = withHreflang(source, langs);
  files.set(sourcePath, rootHtml);
  for (const lang of langs.slice(1)) {
    files.set(path.join(docs, lang, 'index.html'), langPage(rootHtml, lang, rtl));
  }
  files.set(path.join(docs, 'sitemap.xml'), sitemap(langs));
  files.set(path.join(docs, 'robots.txt'), robots);
  return files;
}

const files = build();
if (process.argv.includes('--check')) {
  const stale = [...files].filter(([p, c]) => !fs.existsSync(p) || fs.readFileSync(p, 'utf8') !== c);
  for (const [p] of stale) console.log(`FAIL  out of date: ${path.relative(root, p)}`);
  if (stale.length) {
    console.log('\nRun `node scripts/build-lang-pages.js` after editing docs/index.html.');
    process.exit(1);
  }
  console.log(`ok    ${files.size} generated files are up to date`);
} else {
  for (const [p, c] of files) {
    fs.mkdirSync(path.dirname(p), { recursive: true });
    fs.writeFileSync(p, c);
  }
  console.log(`wrote ${files.size} files`);
}
